def evaluate_model(model, test_data, metrics):
    results = {}
    for metric in metrics:
        scores = []
        for item in test_data:
            prediction = model.predict(item['input'])
            score = metric.calculate(prediction, item['expected_output'])
            scores.append(score)
        results[metric.name] = sum(scores) / len(scores)
    return results
